      const camDir = this.camera.getWorldDirection(this.tmpV2);
      const facing = camDir.dot(this.sunDir);
      post.godRays.uniforms.sunPos.value.set(sp3.x * 0.5 + 0.5, 0.5 - sp3.y * 0.5);
      post.godRays.uniforms.intensity.value = sp3.z < 1 ? MathUtils.smoothstep(facing, 0.05, 0.72) * 0.5 : 0;
      const edge = 1 - MathUtils.smoothstep(Math.max(Math.abs(sp3.x), Math.abs(sp3.y)), 0.8, 0.98);
